head.script:
scwin.fn_closeMsg = function() {
    //alert("메세지"); 
    return true;
    //return confirm("do you close this window?"); // 확인, 취소 버튼이 있는 메세지 창 사용.  
    //return false; // 무조건 닫기 취소. 
}
scwin.trigger1_onclick = function(e) {
    createWindow("WIN1", null, "", "page001", "P0001", "newWindow", "fn_closeMsg", "", "", "", "", "", "scwin.nameLayerHtml");
};
scwin.trigger2_onclick = function(e) {
    createWindow("WIN2", null, "", "page002", "P0002", "newWindow", "fn_closeMsg");
};
scwin.trigger3_onclick = function(e) {
    createWindow("WIN3", null, "", "page003", "P0003", "newWindow", "fn_closeMsg");
};
scwin.nameLayerHtml = function(label, fix, close, layerMenu) {
    //layerMenu를 사용하지 않을 시, return하는 string에 존재하지 않아도 상관없음
    //현재 close 버튼은 오른쪽에 존재하도록 설정됨
    return "<button  id='button1' onclick='" + scwin.nameLayerHtmlFuncName + "(window.event);'>Test</button>" + fix + label + close;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'button1') != null;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    var src;
    window.maxNum = 5;
    window.currentNum = 0;
    windowcheck = function(currentNum) {
        if (currentNum == maxNum) {
            windowContainer1.windows[0].window.close();
            return true;
        } else {
            return false;
        }
    };
    createWindow = function(winId, iconUrl, src, title, id, openAction, closeAction, ar1, ar2, ar3, ar4, ar5, ar6) {
        currentNum = windowContainer1.currentWindowNum;
        windowcheck(currentNum);
        setTimeout(function() {
            windowContainer1.createWindow(winId, iconUrl, src, title, id, openAction, closeAction, ar1, ar2, ar3, ar4, ar5, ar6);
        }, 100);
    };
    scwin.nameLayerHtmlFuncName = scwin.$w.id + "abc";
    window[scwin.nameLayerHtmlFuncName] = function(e) {
        WebSquare.event.stopPropagation(e); //버튼클릭시, 탭이 클릭되는 이벤트를 막기 위함
        console.log("TEST");
    }
}
